sketch.css:
.bar{box-sizing:border-box;width:100%;height:48px;display:flex;align-items:center;gap:12px;padding:0 16px;background:var(--window);color:var(--text);border-bottom:1px solid var(--border);font:13px/1.3 "Segoe UI",system-ui,sans-serif;container-type:inline-size;overflow:hidden}
.bar *{box-sizing:border-box}
.bar svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;flex:none}
.crumbs{display:flex;align-items:center;gap:6px;min-width:0;white-space:nowrap;overflow:hidden}
.crumb{color:var(--muted);cursor:pointer;text-decoration:none;border-radius:4px;padding:2px 2px}
.crumb:hover{color:var(--accent);text-decoration:underline}
.crumb.current{color:var(--text);font-weight:600;cursor:default;text-decoration:none;overflow:hidden;text-overflow:ellipsis}
.sep{color:var(--muted);opacity:.7}
.asof{display:flex;align-items:center;gap:6px;color:var(--muted);font-size:12px;white-space:nowrap;flex:none}
.asof .dot{width:8px;height:8px;border-radius:50%;background:var(--live)}
.asof.stale .dot{background:var(--stale)}
.spacer{flex:1;min-width:8px}
.search{display:flex;align-items:center;gap:6px;height:32px;flex:0 1 320px;min-width:160px;padding:0 10px;border:1px solid var(--border);border-radius:6px;background:var(--background);color:var(--muted)}
.search:focus-within{border-color:var(--accent);background:var(--window)}
.search-input{flex:1;min-width:0;border:0;outline:0;background:transparent;color:var(--text);font:inherit}
.search-input::placeholder{color:var(--muted)}
.search-button,.bell,.user{display:flex;align-items:center;gap:8px;height:32px;border:0;border-radius:6px;background:transparent;color:var(--text);font:inherit;cursor:pointer;flex:none}
.search-button,.bell{width:32px;justify-content:center;position:relative}
.search-button{display:none}
.search-button:hover,.bell:hover,.user:hover{background:var(--hover)}
.badge{position:absolute;top:2px;right:1px;min-width:16px;height:16px;padding:0 4px;border-radius:8px;background:var(--danger);color:#fff;font-size:10px;font-weight:700;line-height:16px;text-align:center;border:1.5px solid var(--window)}
.env{flex:none;height:22px;line-height:20px;padding:0 8px;border-radius:11px;font-size:11px;font-weight:700;letter-spacing:.06em;border:1px solid transparent}
.env.uat{background:var(--warn);color:#1f1600}
.env.dev{background:var(--info);color:#fff}
.env.prod{border-color:var(--danger);color:var(--danger);background:transparent}
.user{padding:0 6px 0 2px}
.avatar{width:30px;height:30px;border-radius:50%;background:var(--accent);color:#fff;font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center;flex:none}
.who{display:flex;flex-direction:column;align-items:flex-start;line-height:1.15;white-space:nowrap}
.who .name{font-weight:600;font-size:12.5px}
.who .role{color:var(--muted);font-size:11px}
.chev{color:var(--muted)}
@container (max-width:900px){.who{display:none}}
@container (max-width:600px){
  .asof{display:none}
  .bar:not(.searching) .search{display:none}
  .bar:not(.searching) .search-button{display:flex}
  .bar.searching .search{flex:1 1 auto;min-width:0}
  .bar.searching .crumbs{display:none}
}

sketch.js:
function render(root, props, fire) {
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const bar = root.querySelector('.bar');

  // breadcrumb: earlier crumbs are links, the last one is the current page
  const crumbs = props.breadcrumb || [];
  const nav = root.querySelector('.crumbs');
  nav.innerHTML = crumbs.map((c, i) => (i ? '<span class="sep">›</span>' : '') +
    (i === crumbs.length - 1 ? '<span class="crumb current">' + esc(c) + '</span>' : '<a class="crumb" data-i="' + i + '">' + esc(c) + '</a>')).join('');
  nav.querySelectorAll('a.crumb').forEach(a => a.onclick = () => fire('crumbClicked', { index: +a.dataset.i }));

  // data freshness
  const asof = root.querySelector('.asof');
  asof.style.display = props.asOfText ? '' : 'none';
  asof.classList.toggle('stale', !!props.asOfStale);
  root.querySelector('.asof-text').textContent = 'Data as of ' + (props.asOfText || '') + (props.asOfStale ? ' · stale' : ' · live');

  // search: Enter submits, Esc clears (and closes the narrow search)
  const input = root.querySelector('.search-input');
  input.placeholder = props.searchPlaceholder || '';
  input.onkeydown = e => {
    if (e.key === 'Enter') fire('searchSubmitted', { text: input.value });
    else if (e.key === 'Escape') { input.value = ''; bar.classList.remove('searching'); }
  };
  input.onblur = () => { if (!input.value) bar.classList.remove('searching'); };
  root.querySelector('.search-button').onclick = () => { bar.classList.add('searching'); input.focus(); };

  // environment badge
  const env = root.querySelector('.env');
  const e = (props.environment || 'None');
  env.className = 'env ' + e.toLowerCase();
  env.textContent = e.toUpperCase();
  env.style.display = e === 'None' ? 'none' : '';

  // alerts
  const n = Math.max(0, props.alertCount | 0);
  const badge = root.querySelector('.badge');
  badge.style.display = n ? '' : 'none';
  badge.textContent = n > 9 ? '9+' : String(n);
  const bell = root.querySelector('.bell');
  bell.title = n ? n + ' alerts' : 'Alerts';
  bell.onclick = () => fire('alertsClicked', {});

  // user
  root.querySelector('.avatar').textContent = props.initials || '';
  root.querySelector('.name').textContent = props.userName || '';
  root.querySelector('.role').textContent = props.userRole || '';
  root.querySelector('.user').onclick = () => fire('userMenuClicked', {});
}
